{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Carebastine, which contains the same 2-methyl-2-carboxypropyl phenyl acid moiety and is zwitterionic at physiological pH, does not cross the blood-brain barrier; this directly transfers to the query's identical acid/zwitterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Oral carebastine required an ID50 of 83.9 mg/kg to inhibit cerebral H1 receptor binding, indicating poor brain penetration; the query shares the same zwitterionic acid motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Carebastine showed limited distribution to the brain in rats, consistent with the query's acid-containing zwitterionic structure limiting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Fexofenadine, another zwitterionic antihistamine bearing the same C(CH3)2COOH group, lacks CNS penetration, supporting a fail prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A close benzimidazole-piperidine analogue without the acid (9d) had a low B/Pb ratio of 0.8 after iv dosing, suggesting the scaffold alone is not strongly brain-penetrant and the query's acid would further reduce access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A close benzimidazole-piperidine analogue without the acid (9n) had B/Pb 2.6, showing the scaffold can be CNS-permeable when the acid is absent; this positive scaffold result is outweighed by the query's zwitterionic acid and charge burden.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Emedastine, sharing the ethoxyethyl benzimidazole but lacking the acid, occupied central H1 receptors in humans, indicating some CNS access; however, this does not transfer to the query because the acid/zwitterion is absent.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "14C-Emedastine showed a brain-to-plasma radioactivity ratio of 1/17, indicating poor brain distribution; this supports the fail direction for the related ethoxyethyl benzimidazole scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Emedastine is classified among second-generation antihistamines that do not penetrate significantly into brain tissue, reinforcing the poor CNS access expected for the query's polar zwitterionic structure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a bilastine-like zwitterionic benzimidazole-piperidine with a free carboxylic acid and basic piperidine. Direct evidence from carebastine and fexofenadine, which share the same C(CH3)2COOH zwitterionic pharmacophore, shows poor or absent CNS penetration. Close benzimidazole-piperidine analogues without the acid show variable B/Pb (0.8-2.6), but the acid/zwitterion and likely efflux liability dominate. Emedastine evidence is mixed but lacks the acid. Overall, the query is predicted to have inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule (bilastine) is present in the evidence set.",
    "Efflux-transporter substrate status of the query is not directly measured, though zwitterionic antihistamines are typically P-gp substrates.",
    "The BUI value for carebastine (56.2%) is not straightforwardly interpretable, but multiple independent records support poor brain penetration."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C13", "C21"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "benzimidazole-piperidine B/Pb analogues"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C15", "C16", "C22"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "emedastine ethoxyethyl benzimidazole"
    },
    {
      "applicability": "high",
      "card_ids": ["C14", "C18", "C19", "C20", "C23"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "carebastine zwitterionic acid"
    },
    {
      "applicability": "high",
      "card_ids": ["C12", "C17"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "fexofenadine zwitterionic acid"
    }
  ],
  "revision_action": "strengthen"
}

